from flask import Flask, jsonify, send_file, request
import os, json, requests
app = Flask(__name__)
BASE_DATA = '/tmp/data' if os.path.exists('/tmp') else 'data'
os.makedirs(BASE_DATA, exist_ok=True)
USERS_FILE = os.path.join(BASE_DATA, 'users.json')
def load_users():
 try:
  if os.path.exists(USERS_FILE):
   with open(USERS_FILE,'r') as f: return json.load(f)
 except: pass
 return {}
def save_users(u):
 with open(USERS_FILE,'w') as f: json.dump(u,f)
def get_user_file(nid):
 safe=nid.replace("@","_at_").replace(".","_")
 return os.path.join(BASE_DATA, f"{safe}.json")
@app.route('/manifest.json')
def manifest():
 return jsonify({"name":"Mi Negocio 11.8.9","short_name":"Mi Negocio","start_url":"/","display":"standalone"})
@app.route('/logo.png')
@app.route('/api/logo.png')
def logo_file():
 for r in ['logo.png','api/logo.png']:
  if os.path.exists(r): return send_file(r, mimetype='image/png')
 return "",204
@app.route('/api/register', methods=['POST'])
def api_register():
 d=request.json; e=d.get('email','').lower().strip(); p=d.get('password','')
 users=load_users(); users[e]={"password":p,"negocio_id":e}; save_users(users)
 fp=get_user_file(e)
 if not os.path.exists(fp):
  with open(fp,'w') as f: json.dump({},f)
 return jsonify({"ok":True})
@app.route('/api/login', methods=['POST'])
def api_login():
 d=request.json; e=d.get('email','').lower().strip(); p=d.get('password','')
 users=load_users()
 if e not in users:
  users[e]={"password":p,"negocio_id":e}; save_users(users)
  fp=get_user_file(e)
  if not os.path.exists(fp):
   with open(fp,'w') as f: json.dump({},f)
  return jsonify({"ok":True,"email":e,"negocio_id":e})
 users[e]['password']=p; save_users(users)
 return jsonify({"ok":True,"email":e,"negocio_id":e})
@app.route('/api/load', methods=['GET'])
def api_load():
 e=request.args.get('email','').lower().strip(); users=load_users()
 if e not in users: users[e]={"password":"temp","negocio_id":e}; save_users(users)
 fp=get_user_file(e); data=json.load(open(fp)) if os.path.exists(fp) else {}
 return jsonify({"ok":True,"data":data})
@app.route('/api/save', methods=['POST'])
def api_save():
 d=request.json; e=d.get('email','').lower().strip(); data=d.get('data',{})
 users=load_users()
 if e not in users: users[e]={"password":"temp","negocio_id":e}; save_users(users)
 with open(get_user_file(e),'w') as f: json.dump(data,f)
 return jsonify({"ok":True})
@app.route('/api/mp/create', methods=['POST'])
def mp_create():
 d=request.json; token=d.get('mp_token','').strip(); amount=float(d.get('amount',0))
 if not token or amount<=0: return jsonify({"ok":False,"msg":"Falta token"}),400
 try:
  r=requests.post("https://api.mercadopago.com/checkout/preferences", headers={"Authorization": f"Bearer {token}","Content-Type":"application/json"}, json={"items":[{"title":d.get('title','Venta'),"quantity":1,"unit_price":amount}]}, timeout=10)
  j=r.json(); link=j.get('init_point') or j.get('sandbox_init_point')
  if not link: return jsonify({"ok":False,"msg":str(j)}),400
  return jsonify({"ok":True,"link":link})
 except Exception as e:
  return jsonify({"ok":False,"msg":str(e)}),500
